SA_XREG_2RAM:
	pop u                           ; C001  fd2a
	lin u                           ; C003  65
	psh u                           ; C004  fda8
	sta ul                          ; C006  2a
	ldi uh,0x78                     ; C007  6878
	lda xh                          ; C009  84
